{
  "query": "query($patientId: ID!) { appointmentsByPatient(patientId: $patientId) { id appointmentId patientId doctorId patientName doctorName dateTime status description eventType receivedAt } }",
  "variables": { "patientId": "{{patientId}}" }
}

{
  "query": "query($doctorId: ID!) { appointmentsByDoctor(doctorId: $doctorId) { id appointmentId patientId doctorId patientName doctorName dateTime status description eventType receivedAt } }",
  "variables": { "doctorId": "{{doctorId}}" }
}

{
  "query": "query { allAppointmentHistories { id appointmentId patientId doctorId patientName doctorName dateTime status description eventType receivedAt } }"
}

{
  "query": "query($id: ID!) { appointmentHistory(id: $id) { id appointmentId patientId doctorId patientName doctorName dateTime status description eventType receivedAt } }",
  "variables": { "id": "{{historyId}}" }
}

{
  "query": "query($patientId: ID!) { upcomingAppointments(patientId: $patientId) { id appointmentId patientId doctorId dateTime status description eventType receivedAt } }",
  "variables": { "patientId": "{{patientId}}" }
}
